INSERT INTO gap_definitions (gap_definition_id, slug, name, title, description, line_of_business, severity, default_severity, rule_id, detection_logic, is_active, scope, version, created_at, updated_at) VALUES ('368c297d-370a-4276-aa32-397aa607ff2b','group_missing_coordination_centre','Coordination Centre (Group)','No coordination centre recorded','No coordination centre (κέντρο συντονισμού) phone number is recorded for this group plan. Employer plans normally give one for pre-authorising hospital admissions — check your certificate of insurance and add it.','group_health','medium','medium','acord_deterministic','{"rules": [{"type": "acord_field_check", "field": "health.coordinationCentre.phone", "operator": "missing"}], "operator": "AND"}'::jsonb,'t','document','2','2026-08-20 09:13:17.829','2026-08-20 09:19:53.89') ON CONFLICT (gap_definition_id) DO UPDATE SET slug=EXCLUDED.slug, name=EXCLUDED.name, title=EXCLUDED.title, description=EXCLUDED.description, line_of_business=EXCLUDED.line_of_business, severity=EXCLUDED.severity, default_severity=EXCLUDED.default_severity, rule_id=EXCLUDED.rule_id, detection_logic=EXCLUDED.detection_logic, is_active=EXCLUDED.is_active, scope=EXCLUDED.scope, version=EXCLUDED.version, updated_at=EXCLUDED.updated_at;
INSERT INTO gap_definitions (gap_definition_id, slug, name, title, description, line_of_business, severity, default_severity, rule_id, detection_logic, is_active, scope, version, created_at, updated_at) VALUES ('e78a4a4a-8795-4ad5-aa26-7f5215c0292d','group_missing_hospital_class','Hospital Room Class (Group)','Hospital room class not recorded','No room class (θέση νοσηλείας) is recorded for this group plan. It decides which room you are entitled to on admission, and it is one of the things people most often assume is better than it is — check your certificate and add it.','group_health','low','low','acord_deterministic','{"rules": [{"type": "acord_field_check", "field": "health.hospitalClass", "operator": "missing"}], "operator": "AND"}'::jsonb,'t','document','2','2026-08-20 09:13:17.829','2026-08-20 09:19:53.89') ON CONFLICT (gap_definition_id) DO UPDATE SET slug=EXCLUDED.slug, name=EXCLUDED.name, title=EXCLUDED.title, description=EXCLUDED.description, line_of_business=EXCLUDED.line_of_business, severity=EXCLUDED.severity, default_severity=EXCLUDED.default_severity, rule_id=EXCLUDED.rule_id, detection_logic=EXCLUDED.detection_logic, is_active=EXCLUDED.is_active, scope=EXCLUDED.scope, version=EXCLUDED.version, updated_at=EXCLUDED.updated_at;
INSERT INTO gap_definitions (gap_definition_id, slug, name, title, description, line_of_business, severity, default_severity, rule_id, detection_logic, is_active, scope, version, created_at, updated_at) VALUES ('c18c1a08-9fab-48db-a9bd-c898d31e2c26','group_no_direct_billing','Direct Settlement (Group)','Direct settlement with the hospital not available','This group plan does not offer απευθείας εξόφληση. You would pay the hospital yourself and claim the money back afterwards, which means having the funds available at the time.','group_health','medium','medium','acord_deterministic','{"rules": [{"type": "acord_field_check", "field": "health.directBillingAvailable", "operator": "is_false"}], "operator": "AND"}'::jsonb,'t','document','2','2026-08-20 09:13:17.829','2026-08-20 09:19:53.89') ON CONFLICT (gap_definition_id) DO UPDATE SET slug=EXCLUDED.slug, name=EXCLUDED.name, title=EXCLUDED.title, description=EXCLUDED.description, line_of_business=EXCLUDED.line_of_business, severity=EXCLUDED.severity, default_severity=EXCLUDED.default_severity, rule_id=EXCLUDED.rule_id, detection_logic=EXCLUDED.detection_logic, is_active=EXCLUDED.is_active, scope=EXCLUDED.scope, version=EXCLUDED.version, updated_at=EXCLUDED.updated_at;
INSERT INTO gap_definitions (gap_definition_id, slug, name, title, description, line_of_business, severity, default_severity, rule_id, detection_logic, is_active, scope, version, created_at, updated_at) VALUES ('fe4b9791-e3bc-4dbc-9d28-8af7a65bac62','insured_value_above_declared','Insured Value vs Declared Value','Το ασφαλισμένο ποσό είναι πολύ πάνω από τη δηλωμένη αξία','Η ασφαλισμένη αξία απέχει σημαντικά από την αξία που δηλώνει το ίδιο το ασφαλιστήριο για το όχημα. Δεν αποζημιώνεστε ποτέ πάνω από την πραγματική αξία, οπότε αξίζει να το συζητήσετε στην επόμενη ανανέωση.','motor','low','low','acord_deterministic','{"rules": [{"type": "acord_field_check", "field": "vehicle.insuredValue", "operator": "value_drift", "direction": "above", "thresholdPct": 20, "referenceField": "vehicle.estimatedMarketValue"}], "operator": "AND"}'::jsonb,'t','document','1','2026-08-21 00:58:32.218','2026-08-21 03:48:42.809') ON CONFLICT (gap_definition_id) DO UPDATE SET slug=EXCLUDED.slug, name=EXCLUDED.name, title=EXCLUDED.title, description=EXCLUDED.description, line_of_business=EXCLUDED.line_of_business, severity=EXCLUDED.severity, default_severity=EXCLUDED.default_severity, rule_id=EXCLUDED.rule_id, detection_logic=EXCLUDED.detection_logic, is_active=EXCLUDED.is_active, scope=EXCLUDED.scope, version=EXCLUDED.version, updated_at=EXCLUDED.updated_at;
INSERT INTO gap_definitions (gap_definition_id, slug, name, title, description, line_of_business, severity, default_severity, rule_id, detection_logic, is_active, scope, version, created_at, updated_at) VALUES ('3ded6164-f9d7-43df-8909-7ddbd8e67bb4','insured_value_below_rebuild_cost','Insured Value vs Rebuild Cost','Το ασφαλισμένο ποσό είναι κάτω από το κόστος ανακατασκευής','Η ασφαλισμένη αξία απέχει σημαντικά από το κόστος ανακατασκευής που αναφέρει το ίδιο το ασφαλιστήριο. Σε τέτοια περίπτωση μπορεί να ενεργοποιηθεί ο όρος αναλογίας, που μειώνει την αποζημίωση ακόμη και σε μερική ζημιά. Αξίζει να το συζητήσετε στην επόμενη ανανέωση.','home','high','high','acord_deterministic','{"rules": [{"type": "acord_field_check", "field": "property.insuredValue", "operator": "value_drift", "direction": "below", "thresholdPct": 20, "referenceField": "property.estimatedRebuildCost"}], "operator": "AND"}'::jsonb,'t','document','1','2026-08-21 00:58:32.218','2026-08-21 00:58:32.218') ON CONFLICT (gap_definition_id) DO UPDATE SET slug=EXCLUDED.slug, name=EXCLUDED.name, title=EXCLUDED.title, description=EXCLUDED.description, line_of_business=EXCLUDED.line_of_business, severity=EXCLUDED.severity, default_severity=EXCLUDED.default_severity, rule_id=EXCLUDED.rule_id, detection_logic=EXCLUDED.detection_logic, is_active=EXCLUDED.is_active, scope=EXCLUDED.scope, version=EXCLUDED.version, updated_at=EXCLUDED.updated_at;
INSERT INTO gap_definitions (gap_definition_id, slug, name, title, description, line_of_business, severity, default_severity, rule_id, detection_logic, is_active, scope, version, created_at, updated_at) VALUES ('41b016a8-c213-4ad3-ad0a-532c1df7161d','missing_accident_declaration_phone','Accident Declaration Number','Accident declaration number not recorded','No accident-declaration telephone number (φιλικός διακανονισμός) is recorded for this policy. Greek motor policies normally print one — check your documents and add it, so it is to hand at the roadside rather than looked for afterwards.','motor','low','low','acord_deterministic','{"rules": [{"type": "acord_field_check", "field": "vehicle.accidentDeclarationPhone", "operator": "missing"}], "operator": "AND"}'::jsonb,'t','document','3','2026-08-20 09:05:07.38','2026-08-20 09:19:53.89') ON CONFLICT (gap_definition_id) DO UPDATE SET slug=EXCLUDED.slug, name=EXCLUDED.name, title=EXCLUDED.title, description=EXCLUDED.description, line_of_business=EXCLUDED.line_of_business, severity=EXCLUDED.severity, default_severity=EXCLUDED.default_severity, rule_id=EXCLUDED.rule_id, detection_logic=EXCLUDED.detection_logic, is_active=EXCLUDED.is_active, scope=EXCLUDED.scope, version=EXCLUDED.version, updated_at=EXCLUDED.updated_at;
