INSERT INTO gap_definitions (gap_definition_id, slug, name, title, description, line_of_business, severity, default_severity, rule_id, detection_logic, is_active, scope, version, created_at, updated_at) VALUES ('5eaf7a7e-3956-4c59-9889-1d7c1e6c0035','missing_emergency_assistance_phone','Emergency Assistance Number','Emergency assistance number not recorded','No 24-hour emergency assistance number is recorded for this policy. Travel policies normally print one — check your documents and add it, so it is on your phone rather than in a drawer at home.','travel','medium','medium','acord_deterministic','{"rules": [{"type": "acord_field_check", "field": "travel.emergencyAssistancePhone", "operator": "missing"}], "operator": "AND"}'::jsonb,'t','document','2','2026-08-20 09:13:17.829','2026-08-20 09:19:53.89') ON CONFLICT (gap_definition_id) DO UPDATE SET slug=EXCLUDED.slug, name=EXCLUDED.name, title=EXCLUDED.title, description=EXCLUDED.description, line_of_business=EXCLUDED.line_of_business, severity=EXCLUDED.severity, default_severity=EXCLUDED.default_severity, rule_id=EXCLUDED.rule_id, detection_logic=EXCLUDED.detection_logic, is_active=EXCLUDED.is_active, scope=EXCLUDED.scope, version=EXCLUDED.version, updated_at=EXCLUDED.updated_at;
INSERT INTO gap_definitions (gap_definition_id, slug, name, title, description, line_of_business, severity, default_severity, rule_id, detection_logic, is_active, scope, version, created_at, updated_at) VALUES ('be594406-c5dd-4742-baa3-ee7fd6f42dc6','missing_enfia_components','ENFIA Coverage Components','Not eligible for the ENFIA discount','Insuring a home against fire, earthquake AND flood qualifies it for a reduction in ENFIA property tax. One or more of the three is missing from this policy.','home','high','high','acord_deterministic','{"rules": [{"type": "acord_field_check", "field": "property", "fields": ["property.fireCoverageIncluded", "property.earthquakeCoverageIncluded", "property.floodCoverageIncluded"], "operator": "all_false"}], "operator": "AND"}'::jsonb,'t','document','4','2026-08-20 02:48:10.016','2026-08-20 09:19:53.89') ON CONFLICT (gap_definition_id) DO UPDATE SET slug=EXCLUDED.slug, name=EXCLUDED.name, title=EXCLUDED.title, description=EXCLUDED.description, line_of_business=EXCLUDED.line_of_business, severity=EXCLUDED.severity, default_severity=EXCLUDED.default_severity, rule_id=EXCLUDED.rule_id, detection_logic=EXCLUDED.detection_logic, is_active=EXCLUDED.is_active, scope=EXCLUDED.scope, version=EXCLUDED.version, updated_at=EXCLUDED.updated_at;
INSERT INTO gap_definitions (gap_definition_id, slug, name, title, description, line_of_business, severity, default_severity, rule_id, detection_logic, is_active, scope, version, created_at, updated_at) VALUES ('f6eef984-7a9a-47f3-a2ee-468808b9fb50','missing_hospital_class','Hospital Room Class','Hospital room class not recorded','No room class (θέση νοσηλείας) is recorded for this policy. Greek health policies state it, and it decides which room you are entitled to on admission — check your documents and add it.','health','low','low','acord_deterministic','{"rules": [{"type": "acord_field_check", "field": "health.hospitalClass", "operator": "missing"}], "operator": "AND"}'::jsonb,'t','document','3','2026-08-20 09:05:07.38','2026-08-20 09:19:53.89') ON CONFLICT (gap_definition_id) DO UPDATE SET slug=EXCLUDED.slug, name=EXCLUDED.name, title=EXCLUDED.title, description=EXCLUDED.description, line_of_business=EXCLUDED.line_of_business, severity=EXCLUDED.severity, default_severity=EXCLUDED.default_severity, rule_id=EXCLUDED.rule_id, detection_logic=EXCLUDED.detection_logic, is_active=EXCLUDED.is_active, scope=EXCLUDED.scope, version=EXCLUDED.version, updated_at=EXCLUDED.updated_at;
