INSERT INTO gap_definitions (gap_definition_id, slug, name, title, description, line_of_business, severity, default_severity, rule_id, detection_logic, is_active, scope, version, created_at, updated_at) VALUES ('b21d0937-198f-4fba-b259-9ba994b620d4','missing_microchip_number','Microchip Number','Microchip number not recorded','No microchip number is recorded for this policy. Microchipping is a legal requirement for dogs in Greece and insurers normally record the number as the animal’s identity — check your documents and add it.','pet','low','low','acord_deterministic','{"rules": [{"type": "acord_field_check", "field": "pet.microchipNumber", "operator": "missing"}], "operator": "AND"}'::jsonb,'t','document','3','2026-08-20 09:05:07.38','2026-08-20 09:19:53.89') ON CONFLICT (gap_definition_id) DO UPDATE SET slug=EXCLUDED.slug, name=EXCLUDED.name, title=EXCLUDED.title, description=EXCLUDED.description, line_of_business=EXCLUDED.line_of_business, severity=EXCLUDED.severity, default_severity=EXCLUDED.default_severity, rule_id=EXCLUDED.rule_id, detection_logic=EXCLUDED.detection_logic, is_active=EXCLUDED.is_active, scope=EXCLUDED.scope, version=EXCLUDED.version, updated_at=EXCLUDED.updated_at;
