INSERT INTO gap_definitions (gap_definition_id, slug, name, title, description, line_of_business, severity, default_severity, rule_id, detection_logic, is_active, scope, version, created_at, updated_at) VALUES ('8eb5d473-3813-495e-9a49-d7cc79f93e59','no_beneficiaries_recorded','Beneficiaries','No beneficiary recorded','No beneficiary (δικαιούχος) is recorded on this policy. With nobody named, the benefit is settled through the estate rather than paid directly — which takes longer, and may not follow what you intended.','life','high','high','acord_deterministic','{"rules": [{"type": "acord_field_check", "field": "beneficiaries", "fields": ["beneficiaries", "lifeAndInvestment.beneficiaries"], "operator": "all_missing"}], "operator": "AND"}'::jsonb,'t','document','3','2026-08-20 09:05:07.38','2026-08-20 09:19:53.89') ON CONFLICT (gap_definition_id) DO UPDATE SET slug=EXCLUDED.slug, name=EXCLUDED.name, title=EXCLUDED.title, description=EXCLUDED.description, line_of_business=EXCLUDED.line_of_business, severity=EXCLUDED.severity, default_severity=EXCLUDED.default_severity, rule_id=EXCLUDED.rule_id, detection_logic=EXCLUDED.detection_logic, is_active=EXCLUDED.is_active, scope=EXCLUDED.scope, version=EXCLUDED.version, updated_at=EXCLUDED.updated_at;
