INSERT INTO gap_definitions (gap_definition_id, slug, name, title, description, line_of_business, severity, default_severity, rule_id, detection_logic, is_active, scope, version, created_at, updated_at) VALUES ('917276ab-13dc-4782-b2c3-a020633f1460','no_earthquake_cover','Earthquake Cover','Earthquake cover not included','This policy states that earthquake (σεισμός) is not covered. Greece is the most seismically active country in Europe, and earthquake is excluded from a standard fire policy unless it is bought explicitly.','home','high','high','acord_deterministic','{"rules": [{"type": "acord_field_check", "field": "property.earthquakeCoverageIncluded", "operator": "is_false"}], "operator": "AND"}'::jsonb,'t','document','3','2026-08-20 09:05:07.38','2026-08-20 09:19:53.89') ON CONFLICT (gap_definition_id) DO UPDATE SET slug=EXCLUDED.slug, name=EXCLUDED.name, title=EXCLUDED.title, description=EXCLUDED.description, line_of_business=EXCLUDED.line_of_business, severity=EXCLUDED.severity, default_severity=EXCLUDED.default_severity, rule_id=EXCLUDED.rule_id, detection_logic=EXCLUDED.detection_logic, is_active=EXCLUDED.is_active, scope=EXCLUDED.scope, version=EXCLUDED.version, updated_at=EXCLUDED.updated_at;
INSERT INTO gap_definitions (gap_definition_id, slug, name, title, description, line_of_business, severity, default_severity, rule_id, detection_logic, is_active, scope, version, created_at, updated_at) VALUES ('a7785bca-0117-4fa4-bb13-7235180345f1','no_fire_cover','Fire Cover','Fire cover not included','This policy states that fire (πυρκαγιά) is not covered. Fire is the base peril of a Greek home policy, and a mortgage lender normally requires it.','home','high','high','acord_deterministic','{"rules": [{"type": "acord_field_check", "field": "property.fireCoverageIncluded", "operator": "is_false"}], "operator": "AND"}'::jsonb,'t','document','3','2026-08-20 09:05:07.38','2026-08-20 09:19:53.89') ON CONFLICT (gap_definition_id) DO UPDATE SET slug=EXCLUDED.slug, name=EXCLUDED.name, title=EXCLUDED.title, description=EXCLUDED.description, line_of_business=EXCLUDED.line_of_business, severity=EXCLUDED.severity, default_severity=EXCLUDED.default_severity, rule_id=EXCLUDED.rule_id, detection_logic=EXCLUDED.detection_logic, is_active=EXCLUDED.is_active, scope=EXCLUDED.scope, version=EXCLUDED.version, updated_at=EXCLUDED.updated_at;
